import json
from pathlib import Path

OUT = Path('data/legal/pilot20_result.jsonl')
REPORT = Path('docs/reports/2026-08-11_판례정규화_파일럿20건.md')

def ev(part, loc):
    return {'source_part': part, 'locator': loc}

def rec(id, source, board, grade, date, finality, issues, facts, holdings, completeness):
    return {
        'generated_by': 'codex-llm', 'verified_by': 'unreviewed',
        'source_completeness': completeness,
        'case': {'id': id, 'source': source, 'source_board': board,
                 'authority_grade': grade, 'date': date, 'finality': finality,
                 'finality_basis': 'source_stated' if source == 'fss' or finality == 'remanded' else 'inferred'},
        'issues': issues, 'facts': facts, 'holdings': holdings,
    }

def issue(n, typ, text):
    return {'issue_id': n, '쟁점유형': typ, '쟁점문구': text}

