def fss(id, board, grade, date, title, fact, issue_text, outcome, summary, loc, part='첨부텍스트'):
    return rec(id,'fss',board,grade,date,'final', [issue('i1','보험금지급',issue_text)],
      [{'fact':fact,'assertion_status':'stated','evidence_ref':ev(part,loc)}],
      [{'issue_id':'i1','결론':outcome,'법리_요약':summary,'confidence':'high','evidence_ref':ev(part,loc)}], 'full_source')

